    [Fact]
    public void Row_gap_percent_wrapping_with_mixed_flexible_content() {
        using var tree = new LayoutTree();

        var root = tree.CreateNode();
        tree.SetPositionType(root, PositionType.Absolute);
        tree.SetFlexDirection(root, FlexDirection.Row);
        tree.SetDimension(root, Dimension.Width, StyleLength.Points(300.0f));
        tree.SetDimension(root, Dimension.Height, StyleLength.Points(300.0f));
        tree.SetGap(root, Gutter.All, StyleLength.Percent(10.0f));

        var rootChild0 = tree.CreateNode();
        tree.SetDimension(rootChild0, Dimension.Width, StyleLength.Points(10.0f));
        tree.InsertChild(root, rootChild0, 0);

        var rootChild1 = tree.CreateNode();
        tree.SetFlexGrow(rootChild1, 1.0f);
        tree.SetFlexShrink(rootChild1, 1.0f);
        tree.SetFlexBasis(rootChild1, StyleLength.Percent(0.0f));
        tree.InsertChild(root, rootChild1, 1);

        var rootChild2 = tree.CreateNode();
        tree.SetDimension(rootChild2, Dimension.Width, StyleLength.Percent(10.0f));
        tree.InsertChild(root, rootChild2, 2);
        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Ltr);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(300.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(10.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(rootChild0), Tolerance);

        Assert.Equal(40.0f, tree.GetLeft(rootChild1), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild1), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(rootChild1), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(rootChild1), Tolerance);

        Assert.Equal(270.0f, tree.GetLeft(rootChild2), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild2), Tolerance);
        Assert.Equal(30.0f, tree.GetWidth(rootChild2), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(rootChild2), Tolerance);

        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Rtl);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(300.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(290.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(10.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(rootChild0), Tolerance);

        Assert.Equal(60.0f, tree.GetLeft(rootChild1), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild1), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(rootChild1), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(rootChild1), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild2), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild2), Tolerance);
        Assert.Equal(30.0f, tree.GetWidth(rootChild2), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(rootChild2), Tolerance);
    }
